  const files = <><header className="px-7 pt-[max(3.25rem,calc(env(safe-area-inset-top)+1.75rem))]"><h1 className="text-[34px] leading-[1.05] font-black tracking-[-0.055em]">文件</h1><p className="mt-2 text-[13px] font-semibold text-[var(--tcp-muted)]">{completedFiles.length ? `已完成 ${completedFiles.length} 个原型文件` : '还没有完成的原型文件'}</p></header><section className="px-7 pb-28 pt-8"><div className="flex items-center justify-between gap-3"><div><p className="text-[20px] font-black tracking-[-0.04em]">全部文件</p><p className="mt-1 text-[12px] font-semibold text-[var(--tcp-muted)]">仅显示当前原型文件库中的项目</p></div><button type="button" onClick={() => setFileSort((value) => value === '最近添加' ? '名称' : '最近添加')} className="rounded-full bg-[var(--tcp-primary-soft)] px-3 py-2 text-[11px] font-black text-[var(--tcp-primary)]">排序 · {fileSort}</button></div><div className="mt-5 rounded-[18px] bg-white/70 p-2"><div className="flex items-center gap-2"><span className="grid h-9 w-9 place-items-center rounded-[12px] bg-[var(--tcp-primary-soft)] text-[var(--tcp-primary)]"><Icon name="folder" size={17} /></span><input value={fileQuery} onChange={(event) => setFileQuery(event.target.value)} placeholder="搜索原型文件名" className="min-w-0 flex-1 bg-transparent text-[13px] font-bold outline-none placeholder:text-[#aaa6af]" aria-label="搜索原型文件名" />{fileQuery && <button type="button" onClick={() => setFileQuery('')} className="px-2 text-[12px] font-black text-[var(--tcp-primary)]">清除</button>}</div></div><div className="mt-3 grid grid-cols-3 rounded-[16px] bg-[var(--tcp-primary-muted)] p-1">{['全部','音频','视频'].map((type) => <button type="button" key={type} onClick={() => setFileFilter(type)} className={`rounded-[12px] py-2 text-[12px] font-black transition ${fileFilter === type ? 'bg-white text-[var(--tcp-primary)] shadow-sm' : 'text-[var(--tcp-muted)]'}`}>{type}</button>)}</div><div className="mt-5 flex items-center justify-between px-1"><p className="text-[12px] font-bold text-[var(--tcp-muted)]">显示文件</p><span className="text-[12px] font-black text-[var(--tcp-primary)]">{visibleFiles.length} 项</span></div><div className="mt-3 space-y-3">{visibleFiles.length ? visibleFiles.map((task) => <article key={task.id} onClick={() => setSelectedTask(task.id)} className="tcp-glass flex cursor-pointer items-center gap-3 rounded-[24px] p-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-[16px] bg-[#e8f5ec] text-[#7ebe9a]"><Icon name="check" size={22}/></span><span className="min-w-0 flex-1"><span className="block truncate font-extrabold">{task.title}</span><span className="mt-1 block text-[12px] font-semibold text-[var(--tcp-muted)]">{task.format}</span></span><Icon name="more" size={18}/></article>) : <div className="tcp-glass grid place-items-center rounded-[30px] px-8 py-12 text-center"><span className="grid h-16 w-16 place-items-center rounded-full bg-[var(--tcp-progress-soft)] text-[var(--tcp-progress-strong)]"><Icon name="folder" size={28}/></span><p className="mt-4 text-[17px] font-extrabold">{completedFiles.length ? '没有匹配的原型文件' : '还没有完成文件'}</p><p className="mt-2 text-[12px] leading-5 font-semibold text-[var(--tcp-muted)]">{completedFiles.length ? '尝试调整关键词或文件类型。' : '完成原型任务后，它会出现在这里；不会读取设备文件。'}</p>{fileQuery && <button type="button" onClick={() => setFileQuery('')} className="mt-3 text-[12px] font-black text-[var(--tcp-primary)]">清除搜索</button>}</div>}</div></section></>
